import{c as s,Q as n,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/zh-cn_formulaimage_0000001855883134.B0WgpEN7.png",p="/assets/SoftmaxGrad%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.CqBo9lZV.png",u=JSON.parse('{"title":"SoftmaxGrad","description":"","frontmatter":{},"headers":[{"level":1,"title":"SoftmaxGrad","slug":"softmaxgrad"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxGrad.md","filePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxGrad.md"}'),r={name:"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxGrad.md"};function o(i,a,d,c,h,m){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="softmaxgrad" tabindex="-1">SoftmaxGrad <a class="header-anchor" href="#softmaxgrad" aria-label="Permalink to &quot;SoftmaxGrad&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将输入tensor[m0, m1, ...mt, n]（t大于等于0）的非尾轴长度相乘的结果看作m，则输入tensor的shape看作[m, n]。对输入tensor[m,n]按行做grad反向计算，计算公式如下：</p><p><img src="'+l+`" alt=""></p><p>当输入shape为ND格式时，内部的reduce过程按last轴进行；当输入shape为NZ格式时，内部的reduce过程按照last轴和first轴进行，reduce过程可以参考<a href="./SoftMax.html">SoftMax</a>中的图示说明。</p><p>为方便理解，通过Python脚本实现的方式，表达其计算公式如下，其中src、grad、isFront是源操作数（输入），dst为目的操作数（输出）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def softmax_grad(grad, src, isFront = None):</span></span>
<span class="line"><span>    dst = grad * src</span></span>
<span class="line"><span>    dst = np.sum(dst, axis=-1, keepdims=True)</span></span>
<span class="line"><span>    if isFront :</span></span>
<span class="line"><span>         return dst</span></span>
<span class="line"><span>    dst = (grad - dst) * src</span></span>
<span class="line"><span>    return dst</span></span></code></pre></div><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>以float类型，ND格式，shape为[m,k]的输入Tensor为例，描述SoftmaxGrad高阶API内部算法框图，如下图所示。</p><p><strong>图 1</strong> SoftmaxGrad算法框图<br><img src="`+p+`" alt="" title="SoftmaxGrad算法框图"></p><p>计算过程分为如下几步，均在Vector上进行：</p><ol><li>mul步骤：对输入x和y所有数据相乘，计算结果会保存到一个临时空间temp中；</li><li>reducesum步骤：对temp数据([m, k])每一行求和得到[m, 1]，计算结果会保存到临时空间中；</li><li>broadcast步骤：对reducesum结果[m, 1]的数据做一个按datablock为单位的填充，比如float类型下，把[m, 1]扩展成[m, 8]；</li><li>判断是否isFront模式，如果是，则输出broadcast后的结果，计算结束；如果不是，则继续执行后续步骤；</li><li>broadcast步骤：对[m, 8]做一个扩维，扩展成[m, k]，计算结果会保存到临时空间中；</li><li>sub步骤：输入x的所有数据减去上一步broadcast后的结果；</li><li>mul步骤：sub后的所有数据和输入y相乘，输出结果z。</li></ol><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false, bool isDataFormatNZ = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxGrad(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; gradTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const SoftMaxTiling&amp; tiling, bool isFront = false, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false, bool isDataFormatNZ = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxGrad(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; gradTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const SoftMaxTiling&amp; tiling, bool isFront = false, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li></ul><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间。临时空间大小BufferSize的获取方式如下：通过<a href="./SoftmaxGrad-Tiling接口.html">SoftmaxGrad Tiling接口</a>中提供的GetSoftMaxGradMaxTmpSize/GetSoftMaxGradMinTmpSize接口获取所需最大和最小临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isReuseSource</td><td>该参数预留，传入默认值false即可。</td></tr><tr><td>isDataFormatNZ</td><td>当前输入输出的数据格式是否为NZ格式，默认数据格式为ND，即默认取值为false。 针对Atlas 200I/500 A2 推理产品，不支持配置为NZ格式。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度需要32Byte对齐，dstTensor的shape与gradTensor，srcTensor的shape一致。</td></tr><tr><td>gradTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度需要32Byte对齐，gradTensor的shape与dstTensor，srcTensor的shape一致。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度需要32Byte对齐，srcTensor的shape与dstTensor，gradTensor的shape一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时空间。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 该操作数的数据类型固定uint8_t。 接口内部复杂计算时用于存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考SoftmaxGrad Tiling接口。</td></tr><tr><td>softmaxShapeInfo</td><td>输入</td><td>srcTensor的shape信息。SoftMaxShapeInfo类型，具体定义如下方代码所示，其中参数的含义为： srcM：非尾轴长度的乘积。srcK：尾轴长度，必须32Byte对齐oriSrcM：原始非尾轴长度的乘积。oriSrcK：原始尾轴长度。 需要注意，当输入输出的数据格式为NZ格式时，尾轴长度为reduce轴长度即图2中的W0<em>W1，非尾轴为H0</em>H1。</td></tr><tr><td>tiling</td><td>输入</td><td>softmaxgrad计算所需tiling信息，Tiling信息的获取请参考SoftmaxGrad Tiling接口。</td></tr><tr><td>isFront</td><td>输入</td><td>是否使能isFront计算，若为True，dstTensor的last轴长度必须固定32Byte。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct SoftMaxShapeInfo {</span></span>
<span class="line"><span>  uint32_t srcM; </span></span>
<span class="line"><span>  uint32_t srcK; </span></span>
<span class="line"><span>  uint32_t oriSrcM;  </span></span>
<span class="line"><span>  uint32_t oriSrcK;  </span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>srcTensor和dstTensor的Tensor空间可以复用。</li><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</li><li>当参数softmaxShapeInfo中srcM != oriSrcM 或者 srcK != oriSrcK时，开发者需要对GM上的原始输入(oriSrcM, oriSrcK)在M或K方向补齐数据到(srcM, srcK)，补齐的数据会参与部分运算，在输入输出复用的场景下，API的计算结果会覆盖srcTensor中补齐的原始数据，在输入输出不复用的场景下，API的计算结果会覆盖dstTensor中对应srcTensor补齐位置的数据。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放SoftmaxGrad计算结果的Tensor</span></span>
<span class="line"><span>// gradLocal：存放SoftmaxGrad计算的输入Tensor</span></span>
<span class="line"><span>// srcLocal：存放SoftmaxGrad计算的输入Tensor</span></span>
<span class="line"><span>// sharedTmpBuffer: 存放SoftmaxGrad计算过程中临时缓存的Tensor</span></span>
<span class="line"><span>// softmaxTiling：存放SoftmaxGrad计算所需Tiling信息，可通过SoftMaxGradTilingFunc接口获取</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::SoftMaxShapeInfo softmaxInfo(</span></span>
<span class="line"><span>    /* 非尾轴长度的乘积          */ srcM, </span></span>
<span class="line"><span>    /* 尾轴长度，必须32Bytes对齐 */ srcK, </span></span>
<span class="line"><span>    /* 原始非尾轴长度的乘积      */ oriSrcM, </span></span>
<span class="line"><span>    /* 原始尾轴长度              */ oriSrcK</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>bool isFront = false;  // 不使能isFront计算</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间</span></span>
<span class="line"><span>AscendC::SoftmaxGrad&lt;T&gt;(dstLocal, gradLocal, srcLocal, sharedTmpBuffer, softmaxTiling, isFront, softmaxInfo);</span></span>
<span class="line"><span>// 接口框架申请临时空间</span></span>
<span class="line"><span>AscendC::SoftmaxGrad&lt;T&gt;(dstLocal, gradLocal, srcLocal, softmaxTiling, isFront, softmaxInfo);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(gradLocal)：</span></span>
<span class="line"><span>[[-100.     -80.     -60.     -50.     -30.     -20.     -15.     -10.   ]</span></span>
<span class="line"><span> [  -9.      -8.      -7.      -6.      -5.      -4.      -3.      -2.   ]</span></span>
<span class="line"><span> [  -1.5     -1.      -0.8     -0.6     -0.5     -0.45    -0.4     -0.35 ]</span></span>
<span class="line"><span> [  -0.3     -0.25    -0.2     -0.15    -0.1     -0.05    -0.01    -0.001]</span></span>
<span class="line"><span> [   0.       0.001    0.01     0.05     0.1      0.15     0.2      0.25 ]</span></span>
<span class="line"><span> [   0.3      0.35     0.4      0.45     0.5      0.6      0.8      1.   ]</span></span>
<span class="line"><span> [   1.5      2.       3.       4.       5.       6.       7.       8.   ]</span></span>
<span class="line"><span> [   9.      10.      15.      20.      30.      50.      60.      80.   ]]</span></span>
<span class="line"><span>输入数据(srcLocal)：</span></span>
<span class="line"><span>[[2. 2. 2. 2. 2. 2. 2. 2.]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [2. 2. 2. 2. 2. 2. 2. 2.]]</span></span>
<span class="line"><span>输出数据(dstLocal)：</span></span>
<span class="line"><span>[[ 1260.     1300.     1340.     1360.     1400.     1420.     1430.     1440.   ]</span></span>
<span class="line"><span> [  158.      160.      162.      164.      166.      168.      170.      172.   ]</span></span>
<span class="line"><span> [   19.4      20.4      20.8      21.2      21.4      21.5      21.6      21.7  ]</span></span>
<span class="line"><span> [    3.644     3.744     3.844     3.944     4.044     4.144     4.224     4.242]</span></span>
<span class="line"><span> [   -3.044    -3.042    -3.024    -2.944    -2.844    -2.744    -2.644    -2.544]</span></span>
<span class="line"><span> [  -17.      -16.9     -16.8     -16.7     -16.6     -16.4     -16.      -15.6  ]</span></span>
<span class="line"><span> [ -143.     -142.     -140.     -138.     -136.     -134.     -132.     -130.   ]</span></span>
<span class="line"><span> [-1078.    -1076.    -1066.    -1056.    -1036.     -996.     -976.     -936.   ]]</span></span></code></pre></div>`,33)])])}const g=s(r,[["render",o]]);export{u as __pageData,g as default};
